import { useEffect, useMemo, useRef } from 'react';
import { useThree } from '@react-three/fiber';
import { EffectComposer, Select, SelectiveBloom } from '@react-three/postprocessing';
import { HalfFloatType, LinearFilter, WebGLRenderTarget } from 'three';
import { BlackHole } from '@/3d/components/BlackHole';
import { BlackHoleBloomMask } from '@/3d/components/BlackHoleBloomMask';
import { RAY_QUALITY } from '@/3d/quality';

export function BlackHoleSystem({ frozen = false, quality = 'high', enableBloom = true }) {
  const size = useThree(state => state.size);
  const dpr = useThree(state => state.viewport.dpr);
  const light = useRef(null);
  const lights = useMemo(() => [light], []);
  const target = useMemo(() => new WebGLRenderTarget(1, 1, {
    type: HalfFloatType, minFilter: LinearFilter, magFilter: LinearFilter,
    depthBuffer: false, stencilBuffer: false,
  }), []);
  useEffect(() => () => target.dispose(), [target]);
  useEffect(() => {
    const tier = RAY_QUALITY[quality];
    const ratio = Math.min(dpr * tier.resolution, tier.maxResolution / Math.max(size.width, size.height));
    target.setSize(Math.max(1, Math.round(size.width * ratio)), Math.max(1, Math.round(size.height * ratio)));
  }, [target, size.width, size.height, dpr, quality]);

  return <>
    <Select enabled><BlackHole target={target} frozen={frozen} quality={quality} /></Select>
    {enableBloom && <>
      <ambientLight ref={light} color="#FFFFFF" />
      <EffectComposer multisampling={0}>
        <SelectiveBloom lights={lights} ignoreBackground mipmapBlur intensity={0.3}
          luminanceThreshold={1.0} luminanceSmoothing={0.15} radius={0.55} />
        <BlackHoleBloomMask texture={target.texture} />
      </EffectComposer>
    </>}
  </>;
}

