import { lazy, Suspense, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { ScrollTrigger, useGSAPSetup } from '@/hooks/useGSAPSetup';
import { useSmoothScroll } from '@/hooks/useSmoothScroll';
import { useScrollProgress } from '@/3d/hooks/useScrollProgress';
import { useLoadingStore } from '@/stores/useLoadingStore';

import Preloader from '@/components/Preloader';
import Cursor from '@/components/Cursor';
import { Nav } from '@/components/layout/Nav';
import { MenuOverlay } from '@/components/layout/MenuOverlay';
import Hero from '@/components/Hero';
import Marquee from '@/components/Marquee';
import About from '@/components/About';
import Work from '@/components/Work';
import Skills from '@/components/sections/Skills';
import Education from '@/components/Education';
import Experience from '@/components/sections/Experience';
import Playground from '@/components/sections/Playground';
import Contact from '@/components/sections/Contact';
import Footer from '@/components/Footer';
import { ThemeToggle } from '@/components/ui/ThemeToggle';

const GalaxyScene = lazy(() => import('@/3d/GalaxyScene').then((module) => ({ default: module.GalaxyScene })));
const OrbitalSkills = lazy(() => import('@/3d/components/OrbitalSkills').then((module) => ({ default: module.OrbitalSkills })));
const Planet = lazy(() => import('@/3d/components/Planet').then((module) => ({ default: module.Planet })));

const availableSections = ['about', 'work', 'skills', 'education', 'experience', 'playground', 'transmission'];

export default function App() {
  const { t } = useTranslation();
  const root = useRef(null);
  const skillsOrbit = useRef(null);
  const aboutPlanet = useRef(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const loading = useLoadingStore((state) => state.isLoading);
  const setLoading = useLoadingStore((state) => state.setLoading);

  useSmoothScroll({ scope: root, paused: loading });
  useScrollProgress({ scope: root });

  useEffect(() => {
    document.body.classList.toggle('loading-lock', loading);
    if (loading) window.scrollTo(0, 0);
    return () => document.body.classList.remove('loading-lock');
  }, [loading]);

  // refresh triggers once intro done + fonts ready (layout shifts)
  useGSAPSetup(() => {
    if (loading) return;
    let active = true;
    const refresh = () => {
      if (active) ScrollTrigger.refresh();
    };
    document.fonts?.ready.then(refresh).catch(() => {});
    const timer = window.setTimeout(refresh, 300);
    window.addEventListener('load', refresh);
    return () => {
      active = false;
      window.clearTimeout(timer);
      window.removeEventListener('load', refresh);
    };
  }, { scope: root, dependencies: [loading], revertOnUpdate: true });

  return (
    <div ref={root} className="noise bg-transparent text-[#1a1a1a] min-h-screen font-sans overflow-x-hidden">
      {loading && <Preloader onComplete={() => setLoading(false)} />}
      <Cursor />
      {/* WIP: enable the remaining links when their sections are mounted. */}
      <Nav availableSections={availableSections} menuOpen={menuOpen} onMenuClick={() => setMenuOpen(true)} />
      <MenuOverlay open={menuOpen} onClose={() => setMenuOpen(false)} availableSections={availableSections} />
      <ThemeToggle />

      <Suspense fallback={null}>
        <GalaxyScene>
          <Planet anchor={aboutPlanet} />
          <OrbitalSkills anchor={skillsOrbit} />
        </GalaxyScene>
      </Suspense>

      <div id="smooth-wrapper" className="z-10">
        <div id="smooth-content" tabIndex={-1}>
          <main>
            <Hero active={!loading} />
            <Marquee text={t('common.marquees.design')} speed={18} />
            <About planetAnchor={aboutPlanet} />
            <Skills orbitAnchor={skillsOrbit} />
            <Education />
            <Experience />
            <Marquee text={t('common.marquees.projects')} speed={22} reverse />
            <Work />
            <Playground />
            <Marquee text={t('common.marquees.collaboration')} speed={20} />
            <Contact />
          </main>

          <Footer />
        </div>
      </div>
    </div>
  );
}

